package generatedbase

import (
	"encoding/base64"
	"github.com/tarekwasfy01/RTDAL---R-Transpiled-Data-Abstraction-Library/toolchain/r2go/runtime"
	"github.com/tarekwasfy01/RTDAL---R-Transpiled-Data-Abstraction-Library/toolchain/r2go/syntax"
)

const programIR = ""

func Load(ctx *runtime.Context) error {
	data, err := base64.StdEncoding.DecodeString(programIR)
	if err != nil {
		return err
	}
	program, err := syntax.DecodeProgramIR(data)
	if err != nil {
		return err
	}
	_, err = ctx.EvalProgram(program)
	return err
}
